 * multiplier is forced to 1.0, so `score === bm25` exactly (parity with
 * #220). In `mode: 'weighted'`, the real config values apply:
 * `recency_mult` is rounded to 2 decimal places (matches the plan section
 * 2.2 worked example's own table, and is what keeps the feature-log
 * property "multiplying the reported fields reproduces `score`" exactly
 * true rather than approximately true).
 */
export function computeMultipliers(
  config: RankingConfig,
  ingredients: { tier: 1 | 2 | 3; aggregator: boolean; quality: 'ok' | 'truncated' | 'unknown'; ageDays: number },
): RankingMultipliers {
  if (config.mode === 'bm25') {
    return { tier_mult: 1.0, aggregator_mult: 1.0, quality_mult: 1.0, recency_mult: 1.0 };
  }
  const rawRecency = Math.pow(0.5, ingredients.ageDays / config.recency.half_life_days);
  return {
    tier_mult: config.tier_mult[String(ingredients.tier) as '1' | '2' | '3'],
    aggregator_mult: ingredients.aggregator ? config.aggregator_mult : 1.0,
    quality_mult: config.quality_mult[ingredients.quality],
    recency_mult: round2(Math.max(config.recency.floor, rawRecency)),
  };
}

export type { RankingMode };

